<template><view class="fund-flow-page"><jk-page-nav title="资金流水"/><view class="flow-content"><view class="tabs"><text v-for="item in filters" :key="item.value" :class="{active:active===item.value}" @tap="active=item.value">{{item.label}}</text></view><view v-for="item in flowRows" :key="item.key" class="flow-row"><jk-icon :name="item.icon" size="lg"/><view class="main"><text>{{item.title}}</text><small>{{item.sourceText}}</small><small>{{item.timeText}}</small></view><view class="right"><strong :class="{negative:item.negative}">{{item.amountText}}</strong><small>{{item.balanceText}}</small></view></view><jk-empty v-if="loaded&&!filteredList.length" text="暂无资金流水"/></view></view></template>
<script>import JkPageNav from'@/components/jk/jk-page-nav.vue';import JkIcon from'@/components/jk/jk-icon.vue';import JkEmpty from'@/components/jk/jk-empty.vue';import{getJkFundFlows}from'@/api/jk.js';import{jkFundFlowTypeText,jkSourceTypeText}from'@/utils/jk-display.js';export default{components:{JkPageNav,JkIcon,JkEmpty},data(){return{list:[],active:'',loaded:false,filters:[{label:'全部',value:''},{label:'收入',value:'income'},{label:'支出',value:'expense'}]}},computed:{filteredList(){return this.list.filter(x=>!this.active||(this.active==='income'?this.amount(x)>=0:this.amount(x)<0))},flowRows(){return this.filteredList.map((item,index)=>{const amount=this.amount(item);return{key:item.id||index,icon:this.icon(item,index),title:item.fundFlowTypeText||item.flowTypeText||this.flowTypeText(item.flowType),sourceText:item.sourceTypeText||this.sourceTypeText(item.sourceType),timeText:this.formatTime(item.createTime),negative:amount<0,amountText:this.signed(amount),balanceText:'余额 ¥'+this.money(item.afterAmount||item.balanceAfter||item.balance)}})}},onShow(){getJkFundFlows({page:1,limit:100}).then(r=>{const d=r.data||r||[];this.list=Array.isArray(d)?d:(d.list||d.records||[])}).catch(()=>this.list=[]).finally(()=>this.loaded=true)},methods:{flowTypeText(v){return jkFundFlowTypeText(v)},sourceTypeText(v){return jkSourceTypeText(v)},amount(i){return Number(i.changeAmount!==undefined?i.changeAmount:(i.amount||0))},money(v){const n=Number(v||0);return Number.isNaN(n)?String(v||'0.00'):n.toFixed(2)},signed(v){const n=Number(v||0);return(n>=0?'+':'')+this.money(n)},formatTime(v){return v?String(v).replace('T',' ').slice(0,19):'-'},icon(i,n){return this.amount(i)>=0?(n%2?'wallet':'money'):'withdraw'}}};</script>
<style scoped>.fund-flow-page{min-height:100vh;background:#fff}.flow-content{padding:0 22rpx 36rpx}.tabs{display:flex;border-bottom:1rpx solid #edf1f0}.tabs text{position:relative;flex:1;padding:20rpx 0;color:#707c82;text-align:center;font-size:23rpx}.tabs text.active{color:#10b981;font-weight:700}.tabs text.active::after{position:absolute;right:36%;bottom:0;left:36%;height:4rpx;background:#10b981;content:''}.flow-row{display:flex;align-items:center;min-height:126rpx;border-bottom:1rpx solid #edf1f0}.main{display:flex;min-width:0;flex:1;flex-direction:column;gap:5rpx;margin-left:10rpx}.main text{color:#273239;font-size:23rpx;font-weight:600}.main small{color:#8b969c;font-size:18rpx}.right{display:flex;flex-direction:column;align-items:flex-end;gap:5rpx}.right strong{color:#10b981;font-size:25rpx}.right strong.negative{color:#ef5b4c}.right small{color:#8b969c;font-size:17rpx}</style>
